From 7dc962a53cb6694d0f7c68658306c7407c16c07d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:31:12 +0100
Subject: [PATCH] faces: Save presets with any title and show whether saving
 worked

The preset id was the title with only spaces removed, so titles with
characters like "/" gave an id KPackage refuses and nothing happened.
Keep only the characters it accepts and say whether saving worked.

BUG: 497773
---
 faces/ConfigAppearance.qml     | 26 +++++++++++++++++++++++++-
 faces/SensorFaceController.cpp | 21 +++++++++++++++++----
 faces/SensorFaceController.h   | 10 ++++++++++
 3 files changed, 52 insertions(+), 5 deletions(-)

diff --git a/faces/ConfigAppearance.qml b/faces/ConfigAppearance.qml
index f32840db..17309f0f 100644
--- a/faces/ConfigAppearance.qml
+++ b/faces/ConfigAppearance.qml
@@ -144,7 +144,31 @@ Kirigami.FormLayout {
             id: saveButton
             icon.name: "document-save"
             text: i18nd("KSysGuardSensorFaces", "Save Settings As Preset")
-            onClicked: controller.savePreset();
+            onClicked: {
+                presetMessage.visible = false;
+                controller.savePreset();
+            }
+        }
+    }
+
+    Kirigami.InlineMessage {
+        id: presetMessage
+        Kirigami.FormData.isSection: true
+        showCloseButton: true
+        visible: false
+    }
+
+    Connections {
+        target: root.controller
+        function onPresetSaved() {
+            presetMessage.type = Kirigami.MessageType.Positive;
+            presetMessage.text = i18nd("KSysGuardSensorFaces", "Saved settings as preset %1.", root.controller.title);
+            presetMessage.visible = true;
+        }
+        function onPresetSaveFailed(errorString) {
+            presetMessage.type = Kirigami.MessageType.Error;
+            presetMessage.text = i18nd("KSysGuardSensorFaces", "Could not save settings as preset: %1", errorString);
+            presetMessage.visible = true;
         }
     }

diff --git a/faces/SensorFaceController.cpp b/faces/SensorFaceController.cpp
index 89fbf8c4..15218d50 100644
--- a/faces/SensorFaceController.cpp
+++ b/faces/SensorFaceController.cpp
@@ -14,6 +14,7 @@
 #include <QJsonDocument>
 #include <QQmlContext>
 #include <QQmlEngine>
+#include <QRegularExpression>
 #include <QTemporaryDir>
 #include <QTimer>

@@ -976,6 +977,7 @@ void SensorFaceController::savePreset()
     // job finished signal below to ensure it lives as long as the job.
     QTemporaryDir dir;
     if (!dir.isValid()) {
+        Q_EMIT presetSaveFailed(dir.errorString());
         return;
     }

@@ -983,17 +985,28 @@ void SensorFaceController::savePreset()

     auto *job = KPackage::PackageJob::install(QStringLiteral("Plasma/Applet"), dir.path());
     connect(job, &KJob::finished, this, [this, dir = std::move(dir)](KJob *job) {
-        if (job->error() == 0 && d->availablePresetsModel) {
-            d->availablePresetsModel->reload();
-        } else {
+        if (job->error() != 0) {
             qCWarning(LIBKSYSGUARD_FACES) << "Failed to install package:" << qPrintable(job->errorString());
+            Q_EMIT presetSaveFailed(job->errorString());
+            return;
         }
+        if (d->availablePresetsModel) {
+            d->availablePresetsModel->reload();
+        }
+        Q_EMIT presetSaved();
     });
 }

 void KSysGuard::SensorFaceController::savePreset(const std::filesystem::path &path)
 {
-    QString pluginName = QStringLiteral("org.kde.plasma.systemmonitor.") + title().simplified().replace(QLatin1Char(' '), QStringLiteral("")).toLower();
+    // KPackage refuses to install a package whose id has anything but ASCII
+    // letters, digits, '_', '-' and '.', so keep only those from the title.
+    QString presetId = title().toLower();
+    presetId.remove(QRegularExpression(QStringLiteral("[^a-z0-9_-]")));
+    if (presetId.isEmpty()) {
+        presetId = QStringLiteral("preset");
+    }
+    QString pluginName = QStringLiteral("org.kde.plasma.systemmonitor.") + presetId;
     int suffix = 0;

     auto presetPackage = KPackage::PackageLoader::self()->loadPackage(QStringLiteral("Plasma/Applet"));
diff --git a/faces/SensorFaceController.h b/faces/SensorFaceController.h
index 5c2f1bd5..56b605fb 100644
--- a/faces/SensorFaceController.h
+++ b/faces/SensorFaceController.h
@@ -254,6 +254,8 @@ public:
     Q_INVOKABLE void loadPreset(const QString &preset);
     /**
      * Save the current configuration as a preset
+     *
+     * This is asynchronous: presetSaved() or presetSaveFailed() is emitted when done.
      */
     Q_INVOKABLE void savePreset();
     void savePreset(const std::filesystem::path &path);
@@ -310,6 +312,14 @@ Q_SIGNALS:
     void updateRateLimitChanged();
     void faceConfigurationChanged();
     void missingSensorsChanged();
+    /**
+     * Emitted when savePreset() installed the preset.
+     */
+    void presetSaved();
+    /**
+     * Emitted when savePreset() could not install the preset.
+     */
+    void presetSaveFailed(const QString &errorString);

 private:
     const std::unique_ptr<SensorFaceControllerPrivate> d;
